CREATE OR REPLACE FUNCTION public.community_create_album(p_title text, p_description text DEFAULT NULL::text, p_member_ids text[] DEFAULT ARRAY[]::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); albumid uuid; x text; begin if pid is null then raise exception 'Perfil PR no encontrado'; end if; if coalesce(trim(p_title),'')='' then raise exception 'Poné un nombre al álbum'; end if; insert into community_albums(owner_id,title,description) values(pid,trim(p_title),nullif(trim(p_description),'')) returning id into albumid; foreach x in array coalesce(p_member_ids,array[]::text[]) loop if x<>pid and community_are_friends(pid,x) then insert into community_album_members(album_id,profile_id) values(albumid,x) on conflict do nothing; end if; end loop; return albumid; end $function$;
