GRANT EXECUTE ON FUNCTION "public"."community_create_album"(p_title text, p_description text, p_member_ids text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."community_create_album"(p_title text, p_description text, p_member_ids text[]) TO "service_role";
CREATE OR REPLACE FUNCTION public.community_create_post(p_body text DEFAULT NULL::text, p_media_paths text[] DEFAULT ARRAY[]::text[], p_tag_profile_ids text[] DEFAULT ARRAY[]::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); postid uuid; x text; n integer:=0; begin if pid is null then raise exception 'Perfil PR no encontrado'; end if; if coalesce(trim(p_body),'')='' and coalesce(array_length(p_media_paths,1),0)=0 then raise exception 'El post necesita texto o fotos'; end if; insert into community_posts(author_id,body) values(pid,nullif(trim(p_body),'')) returning id into postid; foreach x in array coalesce(p_media_paths,array[]::text[]) loop insert into community_post_media(post_id,uploader_id,media_path,sort_order) values(postid,pid,x,n); n:=n+1; end loop; foreach x in array coalesce(p_tag_profile_ids,array[]::text[]) loop if x<>pid and community_are_friends(pid,x) then insert into community_post_tags(post_id,profile_id) values(postid,x) on conflict do nothing; end if; end loop; return postid; end $function$
;
