CREATE OR REPLACE FUNCTION public.community_current_profile_id()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                    select p.id
                                                                                      from public.profiles p
                                                                                        where p.auth_user_id = auth.uid()
                                                                                          limit 1;
                                                                                          $function$
;
