CREATE OR REPLACE FUNCTION public.community_friend_profile(p_target_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare me text:=public.pr_current_profile_id(); r jsonb; begin if me is null or not community_are_friends(me,p_target_id) then raise exception 'Este perfil es privado para tu círculo'; end if; select jsonb_build_object('id',p.id,'nombre',p.nombre,'apellido',p.apellido,'foto',p.foto,'banner',p.banner,'verificado',coalesce(p.verificado,false),'ciudad',case when coalesce(cp.show_city,true) then p.ciudad else null end,'sobre_mi',case when coalesce(cp.show_bio,true) then p.sobre_mi else null end,'instagram',p.instagram,'roller_status',p.roller_status,'profile_accent',p.profile_accent,'setup_patines',p.setup_patines,'showcase',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'slot_key',s.slot_key,'title',s.title,'subtitle',s.subtitle,'image_url',s.image_url,'sort_order',s.sort_order) order by s.sort_order,s.created_at desc),'[]'::jsonb) from pr_profile_showcase s where s.profile_id=p.id),'friend_count',(select count(*) from community_friendships f where p.id in(f.profile_a_id,f.profile_b_id)),'shared_albums',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'owner_id',a.owner_id,'owner_name',op.nombre,'photo_count',(select count(*) from community_album_media am where am.album_id=a.id)) order by a.created_at desc),'[]'::jsonb) from community_albums a join profiles op on op.id=a.owner_id where a.owner_id=p.id or exists(select 1 from community_album_members m where m.album_id=a.id and m.profile_id=p.id and m.status='accepted')),'linked_posts',(select coalesce(jsonb_agg(jsonb_build_object('id',cpst.id,'body',cpst.body,'created_at',cpst.created_at,'author_id',cpst.author_id,'author_name',ap.nombre) order by cpst.created_at desc),'[]'::jsonb) from community_posts cpst join profiles ap on ap.id=cpst.author_id where cpst.deleted_at is null and (cpst.author_id=p.id or exists(select 1 from community_post_tags t where t.post_id=cpst.id and t.profile_id=p.id and t.status='accepted') or exists(select 1 from community_reposts rr where rr.post_id=cpst.id and rr.profile_id=p.id)))) into r from profiles p left join community_privacy cp on cp.profile_id=p.id where p.id=p_target_id; return r; end $function$
;
ALTER FUNCTION "public"."community_friend_profile"(p_target_id text) OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."community_friend_profile"(p_target_id text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_friend_profile"(p_target_id text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_friend_profile"(p_target_id text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."community_friend_profile"(p_target_id text) TO "service_role";
CREATE OR REPLACE FUNCTION public.community_get_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me text;
  incoming jsonb;
  outgoing jsonb;
  friends_list jsonb;
begin
  me := public.community_current_profile_id();

  if me is null then
    raise exception 'No existe un perfil vinculado a esta sesión.';
  end if;

  select coalesce(jsonb_agg(item order by item->>'nombre'), '[]'::jsonb)
  into incoming
  from (
    select jsonb_build_object(
      'id', p.id,
      'nombre', p.nombre,
      'apellido', p.apellido,
      'foto', p.foto,
      'verificado', coalesce(p.verificado, false),
      'role', p.role,
      'participa_como_alumno', coalesce(p.participa_como_alumno, false),
      'ciudad', case when cp.show_city then p.ciudad else '' end,
      'sobre_mi', case when cp.show_bio then p.sobre_mi else '' end,
      'relationship_status', 'incoming',
      'request_id', r.id
    ) as item
    from public.community_friend_requests r
    join public.profiles p on p.id = r.sender_profile_id
    join public.community_privacy cp on cp.profile_id = p.id
    where r.receiver_profile_id = me
      and r.status = 'pending'
  ) incoming_rows;

  select coalesce(jsonb_agg(item order by item->>'nombre'), '[]'::jsonb)
  into outgoing
  from (
    select jsonb_build_object(
      'id', p.id,
      'nombre', p.nombre,
      'apellido', p.apellido,
      'foto', p.foto,
      'verificado', coalesce(p.verificado, false),
      'role', p.role,
      'participa_como_alumno', coalesce(p.participa_como_alumno, false),
      'ciudad', case when cp.show_city then p.ciudad else '' end,
      'sobre_mi', case when cp.show_bio then p.sobre_mi else '' end,
      'relationship_status', 'outgoing',
      'request_id', r.id
    ) as item
    from public.community_friend_requests r
    join public.profiles p on p.id = r.receiver_profile_id
    join public.community_privacy cp on cp.profile_id = p.id
    where r.sender_profile_id = me
      and r.status = 'pending'
  ) outgoing_rows;

  select coalesce(jsonb_agg(item order by item->>'nombre'), '[]'::jsonb)
  into friends_list
  from (
    select jsonb_build_object(
      'id', p.id,
      'nombre', p.nombre,
      'apellido', p.apellido,
      'foto', p.foto,
      'verificado', coalesce(p.verificado, false),
      'role', p.role,
      'participa_como_alumno', coalesce(p.participa_como_alumno, false),
      'ciudad', case when cp.show_city then p.ciudad else '' end,
      'sobre_mi', case when cp.show_bio then p.sobre_mi else '' end,
      'relationship_status', 'friend',
      'request_id', null
    ) as item
    from public.community_friendships f
    join public.profiles p
      on p.id = case
        when f.profile_a_id = me then f.profile_b_id
        else f.profile_a_id
      end
    join public.community_privacy cp on cp.profile_id = p.id
    where me in (f.profile_a_id, f.profile_b_id)
      and not exists (
        select 1
        from public.community_blocks b
        where
          (b.blocker_profile_id = me and b.blocked_profile_id = p.id)
          or
          (b.blocker_profile_id = p.id and b.blocked_profile_id = me)
      )
  ) friend_rows;

  return jsonb_build_object(
    'incoming_requests', incoming,
    'outgoing_requests', outgoing,
    'friends', friends_list
  );
end;
$function$
;
ALTER FUNCTION "public"."community_get_dashboard"() OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."community_get_dashboard"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_get_dashboard"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_get_dashboard"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."community_get_dashboard"() TO "service_role";
