 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); begin if pid is null then raise exception 'Perfil PR no encontrado'; end if; return pid||'/'||regexp_replace(p_kind,'[^a-zA-Z0-9_-]','','g')||'-'||gen_random_uuid()::text||'.'||regexp_replace(lower(p_ext),'[^a-z0-9]','','g'); end $function$
;
