REVOKE ALL ON FUNCTION "public"."community_my_albums"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_my_albums"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_my_albums"() TO "authenticated";
