CREATE OR REPLACE FUNCTION public.community_my_friends()
 RETURNS TABLE(id text, nombre text, apellido text, foto text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ with me as(select public.pr_current_profile_id() id), ids as(select case when f.profile_a_id=me.id then f.profile_b_id else f.profile_a_id end id from community_friendships f cross join me where f.profile_a_id=me.id or f.profile_b_id=me.id) select p.id,p.nombre,p.apellido,p.foto from ids join profiles p using(id) order by p.nombre,p.apellido $function$
;
