CREATE OR REPLACE FUNCTION public.community_my_notifications()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); result jsonb; begin select coalesce(jsonb_agg(jsonb_build_object('id',n.id,'kind',n.kind,'entity_type',n.entity_type,'entity_id',n.entity_id,'text',n.text,'read_at',n.read_at,'created_at',n.created_at,'actor',jsonb_build_object('id',p.id,'nombre',p.nombre,'apellido',p.apellido,'foto',p.foto)) order by n.created_at desc),'[]'::jsonb) into result from (select * from community_notifications where recipient_id=pid order by created_at desc limit 40)n left join profiles p on p.id=n.actor_id; return result; end $function$
;
