CREATE OR REPLACE FUNCTION public.community_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare aid text:=public.pr_current_profile_id(); rid text; nm text; album_title text; begin select coalesce(nombre,'Alguien') into nm from profiles where id=aid; if tg_table_name='community_post_tags' then rid:=new.profile_id; insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(rid,aid,'tag','post',new.post_id,nm||' te etiquetó en una publicación.'); elsif tg_table_name='community_post_comments' then select author_id into rid from community_posts where id=new.post_id; if rid<>aid then insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(rid,aid,'comment','post',new.post_id,nm||' comentó tu publicación.'); end if; elsif tg_table_name='community_post_reactions' then select author_id into rid from community_posts where id=new.post_id; if rid<>aid then insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(rid,aid,'reaction','post',new.post_id,nm||' reaccionó a tu publicación.'); end if; elsif tg_table_name='community_album_members' then rid:=new.profile_id; select title into album_title from community_albums where id=new.album_id; insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(rid,aid,'album_collab_invite','album',new.album_id,nm||' te invitó a colaborar en “'||coalesce(album_title,'un álbum')||'”. Aceptá la invitación para sumar tus fotos y que el álbum también forme parte de tu perfil.'); elsif tg_table_name='community_album_media' then select owner_id into rid from community_albums where id=new.album_id; if rid<>aid then insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(rid,aid,'album_photo','album',new.album_id,nm||' agregó una foto a tu álbum colaborativo.'); end if; end if; return new; end $function$
;
ALTER FUNCTION "public"."community_notify"() OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."community_notify"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_notify"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_notify"() TO "service_role";
CREATE OR REPLACE FUNCTION public.community_notify_album_social()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare aid text:=public.pr_current_profile_id(); rid text; nm text; albumid uuid; begin select coalesce(nombre,'Alguien') into nm from profiles where id=aid; if tg_table_name='community_album_comments' then albumid:=new.album_id; elsif tg_table_name='community_album_reactions' then albumid:=new.album_id; elsif tg_table_name='community_album_photo_comments' then select album_id into albumid from community_album_media where id=new.photo_id; elsif tg_table_name='community_album_photo_reactions' then select album_id into albumid from community_album_media where id=new.photo_id; end if; select owner_id into rid from community_albums where id=albumid; if rid is not null and rid<>aid then insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(rid,aid,case when tg_table_name like '%comments' then 'album_comment' else 'album_reaction' end,'album',albumid,nm||case when tg_table_name like '%comments' then ' comentó en tu álbum.' else ' reaccionó a tu álbum.' end); end if; return new; end $function$
;
ALTER FUNCTION "public"."community_notify_album_social"() OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."community_notify_album_social"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_notify_album_social"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_notify_album_social"() TO "service_role";
CREATE OR REPLACE FUNCTION public.community_notify_new_album()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare nm text; r record; begin select coalesce(nombre,'Alguien') into nm from profiles where id=new.owner_id; for r in select case when f.profile_a_id=new.owner_id then f.profile_b_id else f.profile_a_id end as recipient from community_friendships f where f.profile_a_id=new.owner_id or f.profile_b_id=new.owner_id loop insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(r.recipient,new.owner_id,'new_album','album',new.id,nm||' creó un álbum: '||new.title); end loop; return new; end $function$
;
