CREATE OR REPLACE FUNCTION public.community_notify_new_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare nm text; r record; begin select coalesce(nombre,'Alguien') into nm from profiles where id=new.author_id; for r in select case when f.profile_a_id=new.author_id then f.profile_b_id else f.profile_a_id end as recipient from community_friendships f where f.profile_a_id=new.author_id or f.profile_b_id=new.author_id loop insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(r.recipient,new.author_id,'new_post','post',new.id,nm||' publicó algo nuevo.'); end loop; return new; end $function$
;
