CREATE OR REPLACE FUNCTION public.community_relationship_status(current_profile_id text, target_profile_id text)
 RETURNS TABLE(relationship_status text, request_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                  begin
                                                                                                    if exists (
                                                                                                        select 1
                                                                                                            from public.community_friendships f
                                                                                                                where f.profile_a_id = least(current_profile_id, target_profile_id)
                                                                                                                      and f.profile_b_id = greatest(current_profile_id, target_profile_id)
                                                                                                                        ) then
                                                                                                                            return query select 'friend'::text, null::uuid;
                                                                                                                                return;
                                                                                                                                  end if;

                                                                                                                                    return query
                                                                                                                                      select
                                                                                                                                          case
                                                                                                                                                when r.sender_profile_id = current_profile_id then 'outgoing'
                                                                                                                                                      else 'incoming'
                                                                                                                                                          end,
                                                                                                                                                              r.id
                                                                                                                                                                from public.community_friend_requests r
                                                                                                                                                                  where r.status = 'pending'
                                                                                                                                                                      and (
                                                                                                                                                                            (r.sender_profile_id = current_profile_id and r.receiver_profile_id = target_profile_id)
                                                                                                                                                                                  or
                                                                                                                                                                                        (r.sender_profile_id = target_profile_id and r.receiver_profile_id = current_profile_id)
                                                                                                                                                                                            )
                                                                                                                                                                                              order by r.created_at desc
                                                                                                                                                                                                limit 1;

                                                                                                                                                                                                  if not found then
                                                                                                                                                                                                      return query select 'none'::text, null::uuid;
                                                                                                                                                                                                        end if;
                                                                                                                                                                                                        end;
                                                                                                                                                                                                        $function$
;
