REVOKE ALL ON FUNCTION "public"."community_relationship_status"(current_profile_id text, target_profile_id text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_relationship_status"(current_profile_id text, target_profile_id text) TO "postgres";
