CREATE OR REPLACE FUNCTION public.community_reply_album_comment(p_album_id uuid, p_parent_comment_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); cid uuid; parent_author text; album_title text; actor_name text; begin if not community_can_view_album(p_album_id,pid) then raise exception 'No tenés acceso a este álbum'; end if; if coalesce(trim(p_body),'')='' then raise exception 'Comentario vacío'; end if; select profile_id into parent_author from community_album_comments where id=p_parent_comment_id and album_id=p_album_id; if parent_author is null then raise exception 'El comentario original no existe'; end if; insert into community_album_comments(album_id,profile_id,body,parent_comment_id) values(p_album_id,pid,trim(p_body),p_parent_comment_id) returning id into cid; if parent_author<>pid then select title into album_title from community_albums where id=p_album_id; select coalesce(nombre,'Alguien') into actor_name from profiles where id=pid; insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text) values(parent_author,pid,'album_comment_reply','album',p_album_id,actor_name||' respondió tu comentario en “'||coalesce(album_title,'un álbum')||'”.'); end if; return cid; end $function$
;
