CREATE OR REPLACE FUNCTION public.community_social_feed()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); result jsonb; begin select coalesce(jsonb_agg(x.item order by x.created_at desc),'[]'::jsonb) into result from (select p.created_at,jsonb_build_object('id',p.id,'author_id',p.author_id,'body',p.body,'created_at',p.created_at,'author',jsonb_build_object('nombre',a.nombre,'apellido',a.apellido,'foto',a.foto),'media',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'url',m.media_path,'sort',m.sort_order) order by m.sort_order),'[]'::jsonb) from community_post_media m where m.post_id=p.id),'reactions',(select coalesce(jsonb_agg(jsonb_build_object('profile_id',r.profile_id,'reaction',r.reaction)),'[]'::jsonb) from community_post_reactions r where r.post_id=p.id),'comments',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'profile_id',c.profile_id,'body',c.body,'created_at',c.created_at,'nombre',cp.nombre) order by c.created_at),'[]'::jsonb) from community_post_comments c join profiles cp on cp.id=c.profile_id where c.post_id=p.id),'tags',(select coalesce(jsonb_agg(jsonb_build_object('profile_id',t.profile_id,'status',t.status,'nombre',tp.nombre)),'[]'::jsonb) from community_post_tags t join profiles tp on tp.id=t.profile_id where t.post_id=p.id),'reposted',exists(select 1 from community_reposts rr where rr.post_id=p.id and rr.profile_id=pid),'repost_count',(select count(*) from community_reposts rr where rr.post_id=p.id)) item from community_posts p join profiles a on a.id=p.author_id where p.deleted_at is null and community_are_friends(pid,p.author_id) order by p.created_at desc limit 60) x; return result; end $function$
;
ALTER FUNCTION "public"."community_social_feed"() OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."community_social_feed"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_social_feed"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_social_feed"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."community_social_feed"() TO "service_role";
CREATE OR REPLACE FUNCTION public.community_toggle_album_reaction(p_album_id uuid, p_reaction text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pid text := public.pr_current_profile_id();
  old text;
  ownerid text;
begin
  if not community_can_view_album(p_album_id,pid) then
    raise exception 'No tenés acceso a este álbum';
  end if;

  select reaction into old
  from community_album_reactions
  where album_id=p_album_id and profile_id=pid;

  select owner_id into ownerid from community_albums where id=p_album_id;

  if old=p_reaction then
    delete from community_album_reactions where album_id=p_album_id and profile_id=pid;
    if ownerid is not null and ownerid<>pid then
      delete from community_notifications
      where recipient_id=ownerid and actor_id=pid and entity_type='album' and entity_id=p_album_id
        and kind='album_reaction';
    end if;
    return false;
  end if;

  if old is not null then
    delete from community_album_reactions where album_id=p_album_id and profile_id=pid;
    if ownerid is not null and ownerid<>pid then
      delete from community_notifications
      where recipient_id=ownerid and actor_id=pid and entity_type='album' and entity_id=p_album_id
        and kind='album_reaction';
    end if;
  end if;

  insert into community_album_reactions(album_id,profile_id,reaction)
  values(p_album_id,pid,p_reaction);
  return true;
end
$function$
;
ALTER FUNCTION "public"."community_toggle_album_reaction"(p_album_id uuid, p_reaction text) OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."community_toggle_album_reaction"(p_album_id uuid, p_reaction text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_toggle_album_reaction"(p_album_id uuid, p_reaction text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."community_toggle_album_reaction"(p_album_id uuid, p_reaction text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."community_toggle_album_reaction"(p_album_id uuid, p_reaction text) TO "service_role";
CREATE OR REPLACE FUNCTION public.community_toggle_photo_reaction(p_photo_id uuid, p_reaction text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); aid uuid; old text; begin select album_id into aid from community_album_media where id=p_photo_id; if aid is null or not community_can_view_album(aid,pid) then raise exception 'No tenés acceso a esta foto'; end if; select reaction into old from community_album_photo_reactions where photo_id=p_photo_id and profile_id=pid; if old=p_reaction then delete from community_album_photo_reactions where photo_id=p_photo_id and profile_id=pid; return false; end if; insert into community_album_photo_reactions(photo_id,profile_id,reaction) values(p_photo_id,pid,p_reaction) on conflict(photo_id,profile_id) do update set reaction=excluded.reaction,created_at=now(); return true; end $function$
;
