CREATE OR REPLACE FUNCTION public.community_toggle_reaction(p_post_id uuid, p_reaction text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); old text; begin select reaction into old from community_post_reactions where post_id=p_post_id and profile_id=pid; if old=p_reaction then delete from community_post_reactions where post_id=p_post_id and profile_id=pid; return false; end if; insert into community_post_reactions(post_id,profile_id,reaction) values(p_post_id,pid,p_reaction) on conflict(post_id,profile_id) do update set reaction=excluded.reaction,created_at=now(); return true; end $function$
;
